print(f"Loaded {len(REPAIRS_13_26)} semantic repairs for SKM N2 Part 1 Chapters 13–26.")

updated = 0
for e in exercises:
    eid = e.get("id")
    if eid in REPAIRS_13_26:
        trans, ctx, opt_map = REPAIRS_13_26[eid]
        ch_num = int(eid.split("-c")[1].split("-q")[0])
        evid = f"Shin Kanzen Master N2 Bunpou, Part 1 Chapter {ch_num}, Practice Drills, {CH_PAGES[ch_num]}"
        
        e["translation"] = trans
        e["context"] = ctx
        e["provenance"] = "source-derived"
        e["sourceEvidence"] = evid
        
        # Repair options
        expl = e.get("explanation", {})
        if isinstance(expl, dict):
            for opt in expl.get("options", []):
                txt = opt.get("text", "")
                if opt.get("isCorrect"):
                    continue
                else:
                    if txt in opt_map:
                        opt["reason"] = f"【不正解】{opt_map[txt]}"
                    else:
                        matched = False
                        for k, v in opt_map.items():
                            if k in txt or txt in k:
                                opt["reason"] = f"【不正解】{v}"
                                matched = True
                                break
                        if not matched:
                            opt["reason"] = f"【不正解】文脈・文法関係（{txt}）において不適切です。"
        updated += 1

print(f"Updated {updated} exercises in SKM N2 Part 1 Chapters 13–26.")

with open(EXERCISES_PATH, "w", encoding="utf-8") as f:
    json.dump(exercises, f, ensure_ascii=False, indent=2)

print("Saved updated chapterExercises.json successfully.")
